// The default companion's art, one image per pose.
//
// The art contract, for this folder and for every companion image later
// (uploaded, or generated by NovelAI):
//   - a portrait canvas, taller than wide. 2:3 is expected (NovelAI's 512×768).
//   - the whole character on it, the same canvas size for every pose.
//   - a transparent background, or a plain backdrop that fills the canvas.
//   - the face in roughly the same place in every pose, so one framing fits all.
//
// The SVG files here are placeholders. To use real art, put a PNG or WebP
// with the same name beside them (idle.png, happy.png, proud.png, sleepy.png,
// concerned.png). A PNG or WebP is used in preference to the SVG with no code
// to change, and `framing` below switches to the one for a standing figure.

import { PORTRAIT_FRAMING, type Framing } from "../../src/lib/portrait.ts";

const files = import.meta.glob<string>("./*.{png,webp,svg}", { eager: true, query: "?url", import: "default" });

const PREFERENCE = ["png", "webp", "svg"];

function find(pose: string): { url: string; type: string } | null {
  for (const type of PREFERENCE) {
    const url = files[`./${pose}.${type}`];
    if (url) return { url, type };
  }
  return null;
}

/** The image address for a pose, falling back to the idle pose if that one has no art. */
export function poseImage(pose: string): string {
  return (find(pose) ?? find("idle"))?.url ?? "";
}

/** Where the placeholder's face is. It is a round creature in the middle of its canvas, so the close-up shows all of it. */
const PLACEHOLDER_FRAMING: Framing = { x: 0.5, y: 0.52, span: 0.6 };

/**
 * Where the face is in the default art, for the close-up on Today. Real art
 * is assumed to be a standing figure. If its face sits somewhere else, set
 * the numbers here: x and y are the centre of the face as fractions of the
 * image, and span is how much of the image's height the close-up shows.
 */
export const framing: Framing = find("idle")?.type === "svg" ? PLACEHOLDER_FRAMING : PORTRAIT_FRAMING;
